function mergeMessages(base: Messages, override?: Partial<Messages>): Messages {
  return { ...base, ...override, nav: { ...base.nav, ...override?.nav }, home: { ...base.home, ...override?.home }, workspace: { ...base.workspace, ...override?.workspace }, category: { ...base.category, ...override?.category }, common: { ...base.common, ...override?.common } };
}

export function isLocale(value: string): value is Locale { return (LOCALES as readonly string[]).includes(value); }
export function getMessages(locale: Locale): Messages { return mergeMessages(en, translations[locale]); }
export function getCancelLabel(locale: Locale): string { return ({ ...expandedMap(c => c.status.cancel), ko: "취소", it: "Annulla", en: "Cancel", "zh-CN": "取消", "zh-TW": "取消", es: "Cancelar", "pt-BR": "Cancelar", de: "Abbrechen", fr: "Annuler", ja: "キャンセル" } as Record<Locale, string>)[locale]; }
export function getStatusLabel(locale: Locale, status: "cancelled"): string { return ({ ...expandedMap(c => c.status.cancelled), ko: "취소됨", it: "Annullato", en: "Cancelled", "zh-CN": "已取消", "zh-TW": "已取消", es: "Cancelado", "pt-BR": "Cancelado", de: "Abgebrochen", fr: "Annulé", ja: "キャンセル済み" } as Record<Locale, string>)[locale]; }
export function getLocalePath(locale: Locale, path = ""): string { return `/${locale}${path.startsWith("/") || !path ? path : `/${path}`}`; }

