function replaceNameWords(name: string, locale: Locale): string { let result = name; for (const [from, to] of Object.entries(localizedNamePhrases[locale] ?? {}).sort(([a], [b]) => b.length - a.length)) result = result.replaceAll(from, to); const words = localizedNameWords[locale] ?? {}; for (const [from, to] of Object.entries(words).sort(([a], [b]) => b.length - a.length)) result = result.replace(new RegExp(`\\b${from.replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}\\b`, "g"), to); return result; }
export function getLocalizedToolName(locale: Locale, tool: Tool): string { return isExpandedLocale(locale) ? expandedToolName(locale, tool.name) : locale === "ko" || locale === "it" ? additionalToolName(locale, tool.name) : locale === "en" ? tool.name : replaceNameWords(tool.name, locale); }
export function getLocalizedToolDescription(locale: Locale, tool: Tool): string { if (locale === "en") return tool.shortDescription; const name = getLocalizedToolName(locale, tool); const input = tool.inputFormats.join("、"); const output = tool.outputFormats.join("、"); const templates: Record<Locale, string> = { ...expandedMap(c => formatLocale(c.dynamic.description, { name, input, output })), ko: `${name}: ${input} 입력을 ${output} 형식으로 처리합니다. 옵션과 지원 범위를 확인하세요.`, it: `${name}: elabora ${input} e genera ${output}. Controlla opzioni e limiti prima di scaricare.`, en: `${name}: process ${input} and create ${output}. Review the task options and support limits before downloading.`, "zh-CN": `${name}：处理${input}并生成${output}。下载前请查看任务选项、限制和隐私边界。`, "zh-TW": `${name}：處理${input}並產生${output}。下載前請查看任務選項、限制與隱私邊界。`, es: `${name}: procesa ${input} y crea ${output}. Revisa las opciones, límites y privacidad antes de descargar.`, "pt-BR": `${name}: processe ${input} e crie ${output}. Confira opções, limites e privacidade antes de baixar.`, de: `${name}: ${input} verarbeiten und ${output} erstellen. Optionen, Grenzen und Datenschutz vor dem Download prüfen.`, fr: `${name} : traiter ${input} et créer ${output}. Vérifiez les options, limites et la confidentialité avant le téléchargement.`, ja: `${name}：${input}を処理して${output}を作成します。ダウンロード前にオプション、制限、プライバシーを確認してください。` }; return templates[locale]; }

