export function getToolFaq(locale: Locale, tool: Tool): ToolFaqItem[] {
  const text = faqText[locale];
  const name = getLocalizedToolName(locale, tool);
  const joiner = locale === "ja" || locale.startsWith("zh") ? "、" : ", ";
  const input = tool.inputFormats.join(joiner);
  const output = tool.outputFormats.join(joiner);
  const options = tool.optionSchema.map((option) => getLocalizedOptionLabel(locale, option.label)).join(joiner);
  const modeAnswer = tool.processingMode === "local" ? text.local : text.server;
  const formatsAnswer: Record<Locale, string> = {
    ...expandedMap(c => formatLocale(c.dynamic.formats, { name, input, output })),
  ko: `${name}: ${input} 입력으로 ${output} 결과를 생성합니다. 처리 전에 실제 형식을 확인합니다.`, it: `${name} accetta ${input} e genera ${output}. Il formato effettivo viene verificato prima di elaborare.`,

    en: `${name} accepts ${input} and creates ${output}. The actual file type is checked before processing.`,
    "zh-CN": `${name} 接受 ${input}，生成 ${output}。处理前会检查实际文件类型。`,
    "zh-TW": `${name} 接受 ${input}，產生 ${output}。處理前會檢查實際檔案類型。`,
    es: `${name} acepta ${input} y crea ${output}. El tipo real del archivo se comprueba antes de procesar.`,
    "pt-BR": `${name} aceita ${input} e cria ${output}. O tipo real do arquivo é verificado antes do processamento.`,
    de: `${name} akzeptiert ${input} und erstellt ${output}. Der tatsächliche Dateityp wird vor der Verarbeitung geprüft.`,
    fr: `${name} accepte ${input} et crée ${output}. Le type réel du fichier est vérifié avant le traitement.`,
    ja: `${name} は ${input} を受け付け、${output} を作成します。処理前に実際のファイル形式を確認します。`,
  };
  const optionsAnswer: Record<Locale, string> = {
    ...expandedMap(c => options ? formatLocale(c.dynamic.options, { options }) : c.faq.noOptions),
  ko: options ? "사용 가능한 옵션: " + options + "." : text.noOptions, it: options ? "Opzioni disponibili: " + options + "." : text.noOptions,

    en: options ? `Available controls include: ${options}.` : text.noOptions,
    "zh-CN": options ? `可用控制项包括：${options}。` : text.noOptions,
    "zh-TW": options ? `可用控制項包括：${options}。` : text.noOptions,
    es: options ? `Los controles disponibles incluyen: ${options}.` : text.noOptions,
    "pt-BR": options ? `Os controles disponíveis incluem: ${options}.` : text.noOptions,
    de: options ? `Verfügbare Einstellungen: ${options}.` : text.noOptions,
    fr: options ? `Les réglages disponibles comprennent : ${options}.` : text.noOptions,
    ja: options ? `利用できる設定は ${options} です。` : text.noOptions,
  };
  return [
    { question: text.formats, answer: formatsAnswer[locale] },
    { question: text.mode, answer: modeAnswer },
    // These defaults are persisted as editable content. Live limits belong in the
    // dedicated effective-config section, not a snapshot that becomes stale in FAQ.
    { question: text.options, answer: optionsAnswer[locale] },
  ];
}

